INSERT IGNORE INTO `protocols` (`slug`,`title`,`category`,`tag`,`status`,`version`,`owner`,`summary`,`duration`,`steps`,`notes`) VALUES ('perfusion', 'Perfusion', 'Cell isolation', 'Liver / NPC / Hepa', 'Bản nháp', 'v0.1', 'Lab editor', 'Quy trình phân tách tế bào từ gan, thu NPC và Hepa qua bước ly tâm và gradient Nycodenz.', 'Khoảng 1–2 giờ', '[{"title":"Cân gan","detail":"Ghi lại khối lượng gan trước khi xử lý.","time":"—"},{"title":"Xé và ngâm gan","detail":"Đổ gan ra đĩa Petri, xé gan nhuyễn và ngâm 3–4 phút.","time":"3–4 phút"},{"title":"Lắc tan gan","detail":"Hút hỗn hợp vào bình lắc; lắc bình trong tủ ấm 10–20 phút để tan gan.","time":"10–20 phút"},{"title":"Lọc dịch gan lần 1","detail":"Lọc dịch gan vào 2 falcon 50 mL. Thêm 60 µL DNase I và bổ sung GBSSB tới 50 mL.","time":"—"},{"title":"Đếm lần 1 và ly tâm nhẹ","detail":"Lấy 10 µL để đếm 1. Ly tâm 40 g trong 3 phút ở 4°C. Tách dịch tế bào (NPC) và cặn tế bào (thu Hepa).","time":"3 phút · 4°C"},{"title":"Rửa NPC lần 1","detail":"Thêm 60 µL DNase I vào dịch tế bào, huyền phù, bổ sung GBSSB tới 50 mL. Lấy 10 µL đếm 1. Ly tâm 580 g trong 10 phút ở 4°C.","time":"10 phút · 4°C"},{"title":"Rửa và gộp mẫu","detail":"Hút bớt dịch còn khoảng 10 mL; gộp 2 falcon 50 mL. Bổ sung GBSSB tới 50 mL cùng DNase I và huyền phù.","time":"—"},{"title":"Đếm lần 2 và rửa","detail":"Lấy 10 µL đếm 2. Ly tâm 580 g trong 10 phút ở 4°C. Hút bớt dịch còn khoảng 10 mL, bổ sung 10 mL GBSSB và huyền phù.","time":"10 phút · 4°C"},{"title":"Đếm lần 3 và chuẩn bị gradient","detail":"Lấy 10 µL đếm 3. Thêm 60 µL DNase I vào dịch tế bào, huyền phù. Pha Nycodenz 9,6% rồi cho từ từ Nycodenz vào dịch tế bào.","time":"—"},{"title":"Phân lớp Nycodenz","detail":"Load 2 mL GBSSB. Ly tâm 1800 g trong 18 phút ở 4°C.","time":"18 phút · 4°C"},{"title":"Thu phân lớp HSC","detail":"Hút phân lớp có HSC. Bổ sung GBSSB tới 14 mL và huyền phù. Lấy 10 µL đếm 4.","time":"—"},{"title":"Rửa và chuẩn bị seed","detail":"Ly tâm 580 g trong 10 phút ở 4°C. Hút bỏ dịch, giữ cặn. Bổ sung 1 mL môi trường và huyền phù.","time":"10 phút · 4°C"},{"title":"Đếm và seed","detail":"Lấy 10 µL đếm 4, sau đó seed tế bào theo mật độ thí nghiệm đã được phê duyệt.","time":"—"}]', '["Giữ mẫu lạnh ở các bước xử lý ngoài tủ ấm.","Kiểm tra đúng nồng độ DNase I và Nycodenz trước khi bắt đầu.","Ghi rõ số lần đếm tế bào và phân lớp thu được vào phiếu thí nghiệm.","Quy trình đang ở trạng thái bản nháp; cần review trước khi dùng chính thức."]');
INSERT IGNORE INTO `protocols` (`slug`,`title`,`category`,`tag`,`status`,`version`,`owner`,`summary`,`duration`,`steps`,`notes`) VALUES ('total-protein-extraction', 'Tách Protein Tổng', 'ProtocolEvaluation', 'Protein / Total lysate', 'Đã duyệt', 'v1.0', 'W.Stratos', 'Tách protein tổng từ tế bào bằng TrypLE và RIPA buffer trong điều kiện lạnh.', 'Khoảng 1 giờ', '[{"title":"Kiểm soát nhiệt độ","detail":"Để tránh ảnh hưởng đến hoạt tính của protein, sau khi tách protein, toàn bộ quy trình nên thực hiện ở 4°C.","time":"4°C"},{"title":"Tách tế bào","detail":"Tách tế bào bằng TrypLE.","time":"—"},{"title":"Ly giải bằng RIPA","detail":"Thêm 80 μL RIPA buffer cho mỗi 1 triệu tế bào và vortex 5–10 giây.","time":"5–10 giây"},{"title":"Ủ và trộn mẫu","detail":"Ủ tế bào ở 4°C trong 30 phút; vortex 5–10 giây sau mỗi 5 phút.","time":"30 phút · 4°C"},{"title":"Ly tâm","detail":"Ly tâm ở 13.000 rpm trong 15 phút.","time":"15 phút"},{"title":"Thu protein","detail":"Thu phần dịch nổi chứa protein. Trích 5 μL để đo nồng độ protein.","time":"—"}]', '["Duy trì 4°C trong toàn bộ quy trình sau khi tách protein.","Ghi rõ số lượng tế bào và thể tích RIPA đã sử dụng.","Quy trình được cung cấp bởi người dùng và đã được đưa vào kho quy trình."]');
INSERT IGNORE INTO `protocols` (`slug`,`title`,`category`,`tag`,`status`,`version`,`owner`,`summary`,`duration`,`steps`,`notes`) VALUES ('subcellular-protein-extraction', 'Tách Protein từ nhân/tế bào chất/màng tế bào', 'ProtocolEvaluation', 'Protein / Subcellular fractionation', 'Đã duyệt', 'v1.0', 'W.Stratos', 'Phân tách protein tế bào chất, màng tế bào và phân đoạn nhân từ pellet tế bào.', 'Khoảng 1–2 giờ', '[{"title":"Tách tế bào","detail":"Tách tế bào bằng TrypLE.","time":"—"},{"title":"Giữ pellet tế bào","detail":"Đổ bỏ dung dịch và giữ lại cặn tế bào.","time":"—"},{"title":"Chiết xuất lần 1","detail":"Thêm 100 μL 1X Extraction buffer và huyền phù đều 20–30 lần.","time":"—"},{"title":"Ly tâm phân đoạn","detail":"Ly tâm 2.000 g trong 5 phút ở 4°C. Chuyển phần dịch nổi chứa protein tế bào chất sang epp mới; cặn chứa màng nhân và xác tế bào.","time":"5 phút · 4°C"},{"title":"Lặp lại chiết xuất","detail":"Lặp lại các bước thêm 1X Extraction buffer, huyền phù và ly tâm với phần pellet.","time":"—"},{"title":"Gộp dịch nổi","detail":"Chuyển phần dịch nổi vào epp chứa protein tế bào chất.","time":"—"},{"title":"Ly giải pellet bằng RIPA","detail":"Thêm 50 μL RIPA buffer vào phần pellet.","time":"—"},{"title":"Tách protein màng","detail":"Ly tâm phần protein tế bào chất ở 17.000 g trong 20 phút ở 4°C để thu protein trên màng tế bào.","time":"20 phút · 4°C"},{"title":"Thu các phân đoạn","detail":"Dịch nổi chứa protein tế bào chất; pellet chứa protein màng tế bào. Thêm 50 μL RIPA buffer vào phần pellet.","time":"—"},{"title":"Hoàn tất thu protein","detail":"Thực hiện thu protein từ RIPA buffer như quy trình bình thường.","time":"—"}]', '["Giữ mẫu ở 4°C trong suốt quá trình phân đoạn.","Đánh dấu riêng epp chứa protein tế bào chất, màng tế bào và pellet nhân.","Kiểm tra lực ly tâm theo g, không nhầm với rpm."]');
INSERT IGNORE INTO `protocols` (`slug`,`title`,`category`,`tag`,`status`,`version`,`owner`,`summary`,`duration`,`steps`,`notes`) VALUES ('protein-concentration-bca', 'Đo nồng độ Protein (BCA)', 'ProtocolEvaluation', 'Protein / BCA', 'Đã duyệt', 'v1.0', 'W.Stratos', 'Đo nồng độ protein bằng working solution BCA, đọc hấp thụ tại 562 nm và quy đổi theo phương trình chuẩn.', 'Khoảng 1 giờ', '[{"title":"Chuẩn bị working solution","detail":"Chuẩn bị working solution (WS), 200 μL cho mỗi mẫu/mỗi giếng 96. Thành phần Reagent A:B theo tỷ lệ 50:1.","time":"—"},{"title":"Pha loãng mẫu","detail":"Pha loãng mẫu protein 5 lần và thêm mẫu vào giếng.","time":"—"},{"title":"Thêm working solution","detail":"Thêm 200 μL working solution vào mỗi giếng. Với blank: 200 μL working solution + 25 μL PBS/NaCl/nước.","time":"—"},{"title":"Ủ phản ứng","detail":"Ủ ở 37°C trong 30 phút.","time":"30 phút · 37°C"},{"title":"Đọc tín hiệu","detail":"Đo ở bước sóng 562 nm.","time":"562 nm"},{"title":"Tính nồng độ","detail":"Thay số đo được vào phương trình: ((x − 0.0866) / 0.001007) × 5.","time":"—"},{"title":"Bảo quản mẫu","detail":"Có thể thêm 4X LDS loading buffer để trữ mẫu ở −86°C.","time":"−86°C"},{"title":"Chuẩn bị chạy gel","detail":"Để trữ mẫu lâu dài, sau khi thêm 4X LDS có thể boil mẫu ở 70°C trong 10 phút. Mẫu sau bước này có thể dùng để chạy SDS-PAGE.","time":"10 phút · 70°C"}]', '["Dùng đúng hệ số pha loãng 5 lần khi tính nồng độ.","Luôn có blank để hiệu chỉnh nền.","Ghi lại bước sóng, thời gian ủ và phương trình đã dùng."]');
INSERT IGNORE INTO `protocols` (`slug`,`title`,`category`,`tag`,`status`,`version`,`owner`,`summary`,`duration`,`steps`,`notes`) VALUES ('sds-page-gel-preparation', 'Pha Gel SDS-PAGE', 'ProtocolEvaluation', 'Protein / SDS-PAGE', 'Đã duyệt', 'v1.0', 'W.Stratos', 'Chuẩn bị separating gel và stacking gel cho điện di SDS-PAGE.', 'Khoảng 1 giờ', '[{"title":"Kiểm tra APS","detail":"APS được trữ ở −20°C. Nếu APS có màu trắng đục thay vì trong suốt khi đông đá thì nên bỏ; chỉ nên dùng mỗi aliquot 5–10 lần.","time":"−20°C"},{"title":"Lắp khuôn","detail":"Lắp khuôn đổ gel và kiểm tra khuôn kín, không bị rò.","time":"—"},{"title":"Pha separating gel","detail":"Thêm các thành phần theo đúng thứ tự. TEMED bắt đầu quá trình polymer hóa nên phải cho cuối cùng; TEMED hoạt động và làm đông gel trong khoảng 5 phút sau khi thêm.","time":"Khoảng 5 phút"},{"title":"Đổ separating gel","detail":"Đổ separating gel khoảng 4–4,2 mL. Sau đó thêm Ethanol 100% đến khi ngập khuôn.","time":"—"},{"title":"Chờ gel đông","detail":"Sau 20 phút, đổ bỏ Ethanol và chờ 1–2 phút cho bay hơi.","time":"20 phút"},{"title":"Đổ stacking gel","detail":"Thêm stacking gel khoảng 1 mL đến khi ngập khuôn.","time":"—"},{"title":"Gắn lược","detail":"Dùng khăn giấy đặt dưới khuôn đổ gel và gắn lược. Sau khi gắn lược, gel sẽ tràn ra ngoài; dùng khăn giấy lau khô.","time":"—"},{"title":"Bảo quản gel","detail":"Sau 20 phút gel đông và có thể sử dụng. Có thể trữ gel trong running buffer ở 4°C khoảng 1 tuần.","time":"20 phút · 4°C"}]', '["TEMED phải được thêm cuối cùng và cần thao tác nhanh sau khi thêm.","Kiểm tra khuôn kín trước khi đổ gel.","Loại bỏ APS có dấu hiệu bất thường."]');
INSERT IGNORE INTO `protocols` (`slug`,`title`,`category`,`tag`,`status`,`version`,`owner`,`summary`,`duration`,`steps`,`notes`) VALUES ('western-blot', 'Western Blot', 'ProtocolEvaluation', 'Protein / Western blot', 'Đã duyệt', 'v1.0', 'W.Stratos', 'Điện di SDS-PAGE, chuyển protein sang màng PVDF, ủ kháng thể và phát hiện tín hiệu bằng ECL.', '2 ngày', '[{"title":"Chuẩn bị mẫu","detail":"Nếu chưa boil mẫu, thực hiện boil theo quy trình chuẩn. Mỗi lần chạy SDS-PAGE/Western Blot cần 20–30 μg protein; với protein biểu hiện yếu như E2F1 hoặc GFAP có thể load 50–100 μg.","time":"—"},{"title":"Lắp hệ điện di","detail":"Lắp khuôn gel vào bộ chạy điện di đứng, đổ running buffer ngập khuôn nhưng không để tràn ra ngoài. Bắt đầu tháo lược.","time":"—"},{"title":"Chuẩn bị giếng","detail":"Có thể dùng syringe 1 mL để loại bỏ gel thừa trong các giếng bằng cách hút và bơm vào các giếng.","time":"—"},{"title":"Load mẫu và ladder","detail":"Load mẫu vào các giếng, tối đa 40 μL mỗi giếng, và 5 μL ladder.","time":"—"},{"title":"Chạy điện di","detail":"Chạy máy ở 70 V trong 35 phút, sau đó 120 V trong 70–90 phút.","time":"35 phút + 70–90 phút"},{"title":"Chuẩn bị chuyển màng","detail":"Tháo gel khỏi khuôn điện di, dùng key hoặc cán tháo khuôn gel, rồi chuyển gel qua bể chứa transfer buffer trong lúc setup transfer.","time":"—"},{"title":"Làm lạnh hệ chuyển","detail":"Chuẩn bị đá trong hộp xốp, đặt bộ điện di cùng bộ chuyển màng vào thùng đá. Đặt lên máy khuấy từ, dùng con cá từ nhỏ và khuấy ở 400 rpm.","time":"400 rpm"},{"title":"Chuẩn bị transfer buffer","detail":"Đổ transfer buffer đến 3/4 bồn điện di, thêm đá gel sao cho ngập bồn.","time":"—"},{"title":"Lắp sandwich chuyển màng","detail":"Setup theo thứ tự trong transfer buffer: Xốp đen → giấy lọc → gel → màng PVDF → giấy lọc → xốp đen. Nhúng toàn bộ vật liệu trong transfer buffer.","time":"—"},{"title":"Loại bọt khí","detail":"Đặt gel lên giấy lọc sao cho không có bọt khí. Dùng lăn theo chiều của ladder, phần ngắn nhất của gel, để tránh rách gel và loại hoàn toàn bọt khí.","time":"—"},{"title":"Hoạt hóa màng PVDF","detail":"Hoạt hóa màng PVDF trong methanol 100% trong khoảng 30 giây–1 phút. Rửa màng trong transfer buffer, đặt cẩn thận lên gel và lăn nhẹ để loại bọt khí. Đặt giấy lọc đã thấm transfer buffer lên và lăn thêm một lần.","time":"30 giây–1 phút"},{"title":"Chuyển màng","detail":"Đặt sandwich vào hệ chuyển đúng chiều: đen–đen, trong–đỏ. Chạy ở 100 V trong 1 giờ.","time":"1 giờ · 100 V"},{"title":"Kiểm tra chuyển protein","detail":"Lấy màng và gel ra, đánh dấu mặt nhận protein trên màng PVDF. Nhuộm Ponceau S trong 10 phút để xác nhận chuyển thành công, sau đó lắc rửa trong TBST/PBST trong 10 phút.","time":"20 phút"},{"title":"Block và ủ kháng thể sơ cấp","detail":"Block màng bằng blocking buffer trong 30 phút. Ủ kháng thể sơ cấp qua đêm ở 4°C, sau đó thu hồi kháng thể.","time":"Qua đêm · 4°C"},{"title":"Rửa và ủ kháng thể thứ cấp","detail":"Rửa TBST/PBST mỗi lần 10 phút, tổng cộng 2 lần. Ủ kháng thể thứ cấp trong 1 giờ ở nhiệt độ phòng, vừa ủ vừa lắc. Thu hồi kháng thể và lặp lại bước rửa.","time":"1 giờ · RT"},{"title":"Chuẩn bị phát hiện","detail":"Thấm khô một phần màng, trữ màng trong lớp nylon trong suốt và đặt vào cassette. Chuẩn bị ECL theo tỷ lệ A:B = 1:1.","time":"—"},{"title":"Hiện film","detail":"Toàn bộ quy trình hiện film thực hiện trong buồng tối. Thêm khoảng 250 μL ECL lên màng và đợi 1–3 phút đến khi xuất hiện tín hiệu sáng.","time":"1–3 phút · Buồng tối"},{"title":"Rửa film","detail":"Đặt film X-ray và đợi khoảng 1 phút với tín hiệu mạnh hoặc 30 phút với tín hiệu yếu. Rửa film: developer đến khi xuất hiện band → fixer trong 20 giây → rửa với nước.","time":"20 giây fixer"}]', '["Giữ hệ chuyển lạnh và hạn chế bọt khí trong sandwich.","Mặt nhận protein của màng PVDF phải được đánh dấu trước các bước ủ.","ECL và film phải được thao tác trong điều kiện phù hợp, hiện film trong buồng tối."]');
INSERT IGNORE INTO `protocols` (`slug`,`title`,`category`,`tag`,`status`,`version`,`owner`,`summary`,`duration`,`steps`,`notes`) VALUES ('zymography', 'Zymography', 'ProtocolEvaluation', 'Protein / Zymography', 'Đã duyệt', 'v1.0', 'W.Stratos', 'Phát hiện hoạt tính enzyme bằng gel zymography chứa gelatin và các bước rửa, ủ, nhuộm, tẩy nền.', 'Khoảng 20–26 giờ', '[{"title":"Chuẩn bị mẫu","detail":"Thu hồi môi trường nuôi tế bào, cô đặc bằng màng thẩm tách ở 4.000 g trong 15 phút, sau đó đo nồng độ protein bằng BCA.","time":"15 phút"},{"title":"Pha mẫu non-reducing","detail":"Load mẫu với 5X Non-reducing buffer. Ví dụ: 20 μL mẫu + 5 μL loading buffer.","time":"—"},{"title":"Chuẩn bị gel","detail":"Chuẩn bị gel zymography sử dụng gelatin loại B.","time":"—"},{"title":"Load và chạy gel","detail":"Lắp gel vào bộ điện di đứng, thêm running buffer và đá gel giữ lạnh. Load mẫu cùng ladder vào gel. Chạy 70 V trong 35 phút, sau đó 120 V trong 60 phút.","time":"95 phút"},{"title":"Rửa gel","detail":"Tháo gel khỏi khuôn, chuyển sang hộp chứa washing buffer. Lắc rửa gel 2 lần, mỗi lần 30 phút.","time":"60 phút"},{"title":"Ủ hoạt tính enzyme","detail":"Ủ gel trong incubation buffer từ 18–24 giờ ở 37°C.","time":"18–24 giờ · 37°C"},{"title":"Rửa gel sau ủ","detail":"Rửa gel trong PBST/TBST/nước trong 5 phút.","time":"5 phút"},{"title":"Nhuộm và tẩy nền","detail":"Nhuộm gel bằng Coomassie Blue trong 40 phút. Destain gel bằng destain solution đến khi các band hiện rõ, khoảng 1 giờ.","time":"Khoảng 1 giờ 40 phút"}]', '["Giữ lạnh trong quá trình điện di.","Không dùng reducing buffer nếu cần bảo toàn hoạt tính enzyme.","Thời gian incubation có thể kéo dài 18–24 giờ tùy tín hiệu cần phát hiện."]');
